<template><div class="preview-wrap" ref="wrapper"><div class="preview-canvas" :style="{width:`${canvasSize.width}px`,height:`${canvasSize.height}px`}"><template v-for="clip in visual" :key="clip.id"><div class="visual-layer" :style="layerStyle(clip)"><img v-if="clip.kind==='image'" :src="assetMedia(projectId,clip.assetId!)" :alt="clip.name" :style="{objectFit:clip.fit==='stretch'?'fill':clip.fit}"/><video v-else-if="clip.kind==='video'" :ref="el=>bind(clip.id,el)" :src="assetMedia(projectId,clip.assetId!)" muted playsinline preload="auto" @loadedmetadata="syncMedia" :style="{objectFit:clip.fit==='stretch'?'fill':clip.fit}"/><div v-else class="text-layer" :style="{fontSize:`${clip.fontSize/state.width*canvasWidth}px`,color:clip.color}">{{clip.text}}</div></div></template><audio v-for="clip in audio" :key="clip.id" :ref="el=>bind(clip.id,el)" :src="assetMedia(projectId,clip.assetId!,clip.kind==='audio'?'audio':undefined)" preload="auto" @loadedmetadata="syncMedia"/></div></div></template>
<script setup lang="ts">
import {computed,watch,ref,onMounted,onBeforeUnmount,type ComponentPublicInstance} from 'vue';import {assetMedia,type VideoState,type VideoClip} from '@/api/videoEditor'
import {fitPreview} from '@/utils/videoPreview'
const props=defineProps<{state:VideoState;projectId:string;frame:number;playing:boolean}>(),wrapper=ref<HTMLElement>(),available=ref({width:640,height:360}),elements=new Map<string,HTMLMediaElement>();let observer:ResizeObserver|undefined
const canvasSize=computed(()=>fitPreview(props.state.width,props.state.height,available.value.width,available.value.height)),canvasWidth=computed(()=>canvasSize.value.width)
const active=computed(()=>props.state.clips.filter(c=>props.frame>=c.at&&props.frame<c.at+c.length));const visual=computed(()=>active.value.filter(c=>c.kind!=='audio').sort((a,b)=>props.state.tracks.findIndex(t=>t.id===a.trackId)-props.state.tracks.findIndex(t=>t.id===b.trackId)));const audio=computed(()=>props.state.clips.filter(c=>c.kind==='audio'))
let audioContext:AudioContext|undefined
const gains=new Map<string,GainNode>(),sources=new WeakMap<HTMLMediaElement,MediaElementAudioSourceNode>()
function bind(id:string,element:Element|ComponentPublicInstance|null){if(element instanceof HTMLMediaElement){elements.set(id,element);if(element instanceof HTMLAudioElement){audioContext??=new AudioContext();let source=sources.get(element);if(!source){source=audioContext.createMediaElementSource(element);sources.set(element,source)}if(!gains.has(id)){const gain=audioContext.createGain();source.connect(gain).connect(audioContext.destination);gains.set(id,gain)}}}else{const previous=elements.get(id),gain=gains.get(id);if(previous&&gain)sources.get(previous)?.disconnect(gain);elements.delete(id);gain?.disconnect();gains.delete(id)}}
function layerStyle(clip:VideoClip){return {transform:`translate(${clip.x/props.state.width*100}%,${clip.y/props.state.height*100}%) scale(${clip.scale})`,zIndex:props.state.tracks.findIndex(t=>t.id===clip.trackId)}}
function syncMedia(){if(props.playing)void audioContext?.resume();for(const clip of props.state.clips){const element=elements.get(clip.id);if(!element)continue;const isActive=props.frame>=clip.at&&props.frame<clip.at+clip.length;const time=(props.frame-clip.at+clip.in)/24;if(isActive&&Number.isFinite(element.duration)&&Math.abs(element.currentTime-time)>(props.playing?1/24+.012:.0005))element.currentTime=Math.max(0,time);const relative=props.frame-clip.at;const fade=Math.min(1,clip.fadeIn?relative/clip.fadeIn:1,clip.fadeOut?(clip.length-relative)/clip.fadeOut:1);element.volume=clip.kind==='audio'?1:0;const gain=gains.get(clip.id);if(gain)gain.gain.value=clip.muted?0:clip.volume*Math.max(0,fade);if(isActive&&props.playing)void element.play().catch(()=>{});else element.pause()}}
watch(()=>[props.frame,props.playing,props.state],syncMedia,{deep:true,flush:'post'})
onMounted(()=>{observer=new ResizeObserver(([entry])=>{if(entry)available.value={width:entry.contentRect.width,height:entry.contentRect.height}});if(wrapper.value)observer.observe(wrapper.value)});onBeforeUnmount(()=>{observer?.disconnect();for(const element of elements.values())element.pause();void audioContext?.close()})
</script>
<style scoped>.preview-wrap{display:grid;place-items:center;background:#080c12;height:100%;width:100%;padding:12px;box-sizing:border-box;overflow:hidden;min-width:0;min-height:0}.preview-canvas{position:relative;overflow:hidden;background:#000}.visual-layer{position:absolute;inset:0;transform-origin:center}.visual-layer img,.visual-layer video{width:100%;height:100%}.text-layer{width:90%;height:100%;margin:auto;display:flex;align-items:center;justify-content:center;white-space:pre-wrap;text-align:center;line-height:1.2;font-family:SimHei,'Microsoft YaHei',sans-serif}</style>
